const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Mount Etna location
  const etnaLon = 15.0;
  const etnaLat = 37.73;
  const etnaPoint = ee.Geometry.Point([etnaLon, etnaLat]);

  // Define analysis region (box around Etna, ~50 km extent)
  const region = ee.Geometry.Rectangle([14.5, 37.3, 15.5, 38.2]);

  // Target date: February 23, 2021
  const startDate = '2021-02-23';
  const endDate = '2021-02-24';

  // Sentinel-5P SO2 data for volcanic plume detection
  let collection = ee.ImageCollection('COPERNICUS/S5P/TROPOMI_L3_SO2')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  const imageCount = collection.size().getInfo();
  console.log(`S5P SO2 images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('Attempting Sentinel-2 for aerosol detection...');
    collection = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(startDate, endDate)
      .filterBounds(region)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
    const s2Count = collection.size().getInfo();
    console.log(`Sentinel-2 images found: ${s2Count}`);

    if (s2Count === 0) {
      console.log('C1');
      return;
    }

    // Use Sentinel-2 approach with aerosol bands
    const img = collection.first();
    const validPixels = img.select('B1').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    console.log(`Valid pixels (Sentinel-2): ${validPixels.B1 || 0}`);
    if (!validPixels.B1 || validPixels.B1 === 0) {
      console.log('C2');
      return;
    }
    console.log('B');
    return;
  }

  // Process first S5P image
  const img = collection.first();

  // SO2 column density
  const so2Band = img.select('SO2_column_number_density');

  // Sample SO2 at volcano center and western region
  const centerSO2 = so2Band.sample(etnaPoint, 3000).first().get('SO2_column_number_density').getInfo();

  const westPoint = ee.Geometry.Point([etnaLon - 0.3, etnaLat]);
  const westSO2 = so2Band.sample(westPoint, 3000).first().get('SO2_column_number_density').getInfo();

  const eastPoint = ee.Geometry.Point([etnaLon + 0.3, etnaLat]);
  const eastSO2 = so2Band.sample(eastPoint, 3000).first().get('SO2_column_number_density').getInfo();

  // Check valid pixels in region
  const validPixels = so2Band.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = validPixels.SO2_column_number_density || 0;
  console.log(`Valid SO2 pixels: ${pixelCount}`);

  if (!pixelCount || pixelCount === 0) {
    console.log('C2');
    return;
  }

  // Check for NaN/null values
  if (centerSO2 === null || centerSO2 === undefined || isNaN(centerSO2)) {
    console.log('C3');
    return;
  }

  console.log(`Center SO2: ${centerSO2 !== null ? centerSO2.toFixed(2) : 'null'}`);
  console.log(`West SO2: ${westSO2 !== null ? westSO2.toFixed(2) : 'null'}`);
  console.log(`East SO2: ${eastSO2 !== null ? eastSO2.toFixed(2) : 'null'}`);

  // Determine if plume went westward
  // Plume went west if: west SO2 > center SO2 (higher concentration to the west)
  const plumethreshold = 0.0005; // mol/m^2
  const westPlume = (westSO2 !== null && westSO2 > plumethreshold) && 
                     (westSO2 > (centerSO2 || 0) * 0.8);

  console.log(`SO2 elevated westward: ${westPlume}`);

  if (westPlume) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
